/*
 * Petallica
 *
 * Made for the #WCCChallenge created by Raphaël de Courville
 * 2024/09/05
 */

var spirals = [];

function setup() {
	createCanvas(windowWidth, windowHeight);
	background(255);

	setInterval(() => {

		let origin = createVector(
			~~random(0, width),
			~~randomGaussian(height*0.75, height*0.05) // ~~random(0, height)
		);

		let len = ~~random(width * 1.5, width * 0.5); // ~~random(width / 10, width / 5);
		let nSegments = floor(random(1, 10));
		let spiral = {
			segments : [],
			origin,
			len
		};

		let vectorPos2 = createVector(0, len);
		let ang = 0;

		for (let j = 0; j < nSegments; ++j) {

			let pos = p5.Vector.rotate(vectorPos2, ang);
			spiral.segments.push({
				pos,
				c : color(
					~~random(64, 255),
					~~random(0, 128),
					~~random(32, 192)
				)
			});

			ang += (TWO_PI / nSegments);
		}

		if (spirals.length < width * 0.025) spirals.push(spiral);
	}, 2000);
}

function draw() {
	fill(255, 0.5);
	// rect(0, 0, width, height);

	spirals.forEach((spiral) => {

		push();
		translate(
			spiral.origin.x, 
			spiral.origin.y
		);

		spiral.segments.forEach((segment) => {

			if (segment.pos.mag() > 1) {
				const dst = segment.pos.mag() / spiral.len;
				const clr = segment.c;
				clr.setAlpha(dst > 0.1 ? dst*160 : 10)
				// console.log(dst, spiral.len/(dst+0.0001)*500)
				stroke(clr)
				line(random(-2, 2), random(-2, 2), segment.pos.x+random(-2, 2), segment.pos.y+random(-2, 2));
				segment.pos.setHeading(segment.pos.heading() + PI / 50);
				segment.pos.setMag(segment.pos.mag() - 0.5);
			}

		});
		pop();
	});
}
